HttpRequest request = HttpRequest.newBuilder()
    .uri(URI.create("https://api.enrichlayer.com/v3/person?profile=https%3A%2F%2Flinkedin.com%2Fin%2Fsatyanadella%2F&personalEmail=include"))
    .header("Authorization", "Bearer YOUR_API_KEY")
