using var client = new HttpClient();
client.DefaultRequestHeaders.Authorization =
    new AuthenticationHeaderValue("Bearer", "YOUR_API_KEY");

var person = await client.GetStringAsync("https://api.enrichlayer.com/v3/person?profile=https%3A%2F%2Flinkedin.com%2Fin%2Fsatyanadella%2F&personalEmail=include");

